// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // We fuzz: an arbitrary sender address (as actor) and a single recipient in an array,
    // plus a value v. The helper RevertingOrRecording will expose behavior differences
    // depending on whether the selector matches a declared function.
    function testFuzz_property(address sender, address maybeOther, uint256 v) public {
        // Keep addresses non-zero to avoid trivial rejections
        vm.assume(sender != address(0));
        vm.assume(maybeOther != address(0));
        // Build a single-element _tos array to make external calls occur exactly once
        address[] memory tos = new address[](1);
        tos[0] = maybeOther;

        // Deploy a helper that DECLARES the expected selector signature exactly as the reference does:
        // function transferFrom(address from, address to, uint256 amt) external returns (bool) { ... }
        // It will revert if that function ABI is NOT invoked correctly (i.e., when selector mismatches),
        // and return true otherwise. This lets us observe whether c's low-level call succeeded.
        ReceiverRecorder rec = new ReceiverRecorder();

        // We will call c.transfer with 'from' = sender, 'caddress' = address(rec), _tos = tos, v = v
        // The property: reference C always returns true (does not revert) for any non-empty tos,
        // because it encodes the correct selector; the mutant may produce a failing call when selector is wrong.

        bool ok;
        try c.transfer(sender, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation must never revert for any admissible input (non-empty tos).
        // The mutant that uses the wrong selector can cause the callee's typed function NOT to match,
        // which our ReceiverRecorder treats as a failure (it will fallback and revert).
        assertTrue(ok);
    }
}

// Helper contract that declares the exact function signature the reference encodes.
// If called with the correct selector transferFrom(address,address,uint256) it records the args and returns true.
// If called with a mismatched selector (e.g. transferFrom(...,uint32)) the low-level call will hit fallback
// and this fallback deliberately reverts to make the difference observable.
contract ReceiverRecorder {
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;
    uint public calls;

    // The exact function expected by the correct contract's selector
    function transferFrom(address from, address to, uint256 amt) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastAmount = amt;
        calls += 1;
        return true;
    }

    // Any other selector (mismatch) will hit this fallback; revert to expose the failure.
    fallback() external payable {
        revert("selector mismatch or malformed call");
    }

    receive() external payable {
        // revert on plain ETH transfers to avoid silent success
        revert("no plain transfers");
    }
}
